INSERT OR REPLACE INTO public_sources(id,book,start_chapter,start_verse,end_chapter,end_verse,kind,title,content_json,version,rights_status,active) VALUES('act-16-6-7','ACT','16','6','16','7','scripture','使徒 16:6–7（英語原文: WEB）','{"id":"act-16-6-7","book":"ACT","start":{"chapter":16,"verse":6},"end":{"chapter":16,"verse":7},"spoilerEnd":{"chapter":16,"verse":7},"kind":"scripture","title":"使徒 16:6–7（英語原文: WEB）","text":"When they had gone through the region of Phrygia and Galatia, they were forbidden by the Holy Spirit to speak the word in Asia. When they had come opposite Mysia, they tried to go into Bithynia, but the Spirit didn’t allow them.","url":"https://ebible.org/engwebp/ACT16.htm#V6","version":"WEB-engwebp-checked-2026-10-13","license":"public-domain","generationAllowed":true,"visibility":"public","reviewed":true,"claims":[{"id":"spirit-stops","kind":"fact","text":"本文は、アジアで語ることとビティニアへ進むことが聖霊によって止められたと述べます。止められ方の具体的な仕組みは、この2節には書かれていません。","evidenceQuote":"they were forbidden by the Holy Spirit to speak the word in Asia"},{"id":"spirit-reading","kind":"faith","tradition":"キリスト教の一つの読み方","text":"伝道の行き先も神の導きの中にある、という信仰的な読み方ができます。これは本文の記述からの解釈です。","evidenceQuote":"but the Spirit didn’t allow them."}]}','WEB-engwebp-checked-2026-10-13','approved','1');
INSERT OR REPLACE INTO public_sources(id,book,start_chapter,start_verse,end_chapter,end_verse,kind,title,content_json,version,rights_status,active) VALUES('act-17-6-9','ACT','17','6','17','9','scripture','使徒 17:6–9（英語原文: WEB）','{"id":"act-17-6-9","book":"ACT","start":{"chapter":17,"verse":6},"end":{"chapter":17,"verse":9},"spoilerEnd":{"chapter":17,"verse":9},"kind":"scripture","title":"使徒 17:6–9（英語原文: WEB）","text":"When they didn’t find them, they dragged Jason and certain brothers before the rulers of the city, crying, “These who have turned the world upside down have come here also, whom Jason has received. These all act contrary to the decrees of Caesar, saying that there is another king, Jesus!” The multitude and the rulers of the city were troubled when they heard these things. When they had taken security from Jason and the rest, they let them go.","url":"https://ebible.org/engwebp/ACT17.htm#V6","version":"WEB-engwebp-checked-2026-10-13","license":"public-domain","generationAllowed":true,"visibility":"public","reviewed":true,"claims":[{"id":"jason-security","kind":"fact","text":"ヤソンは一行を迎え入れたとして訴えられ、町の当局はヤソンたちから保証を取って釈放しました。保証の具体的な条件や金額は書かれていません。","evidenceQuote":"When they had taken security from Jason and the rest, they let them go."},{"id":"jason-inference","kind":"inference","text":"騒ぎの再発を抑えるための保証だった可能性はありますが、詳しい制度はこの本文だけでは確定できません。","evidenceQuote":"The multitude and the rulers of the city were troubled"}]}','WEB-engwebp-checked-2026-10-13','approved','1');
INSERT OR REPLACE INTO public_sources(id,book,start_chapter,start_verse,end_chapter,end_verse,kind,title,content_json,version,rights_status,active) VALUES('act-18-1','ACT','18','1','18','1','scripture','使徒 18:1（英語原文: WEB）','{"id":"act-18-1","book":"ACT","start":{"chapter":18,"verse":1},"end":{"chapter":18,"verse":1},"spoilerEnd":{"chapter":18,"verse":1},"kind":"scripture","title":"使徒 18:1（英語原文: WEB）","text":"After these things Paul departed from Athens and came to Corinth.","url":"https://ebible.org/engwebp/ACT18.htm#V1","version":"WEB-engwebp-checked-2026-10-13","license":"public-domain","generationAllowed":true,"visibility":"public","reviewed":true,"claims":[{"id":"arrives-corinth","kind":"fact","text":"この場面では、パウロはアテネを離れてコリントに来ています。","evidenceQuote":"Paul departed from Athens and came to Corinth."}]}','WEB-engwebp-checked-2026-10-13','approved','1');
INSERT OR REPLACE INTO public_sources(id,book,start_chapter,start_verse,end_chapter,end_verse,kind,title,content_json,version,rights_status,active) VALUES('act-18-2-3','ACT','18','2','18','3','scripture','使徒 18:2–3（英語原文: WEB）','{"id":"act-18-2-3","book":"ACT","start":{"chapter":18,"verse":2},"end":{"chapter":18,"verse":3},"spoilerEnd":{"chapter":18,"verse":3},"kind":"scripture","title":"使徒 18:2–3（英語原文: WEB）","text":"He found a certain Jew named Aquila, a man of Pontus by race, who had recently come from Italy with his wife Priscilla, because Claudius had commanded all the Jews to depart from Rome. He came to them, and because he practiced the same trade, he lived with them and worked, for by trade they were tent makers.","url":"https://ebible.org/engwebp/ACT18.htm#V2","version":"WEB-engwebp-checked-2026-10-13","license":"public-domain","generationAllowed":true,"visibility":"public","reviewed":true,"claims":[{"id":"aquila-priscilla","kind":"fact","text":"アキラはポントス出身のユダヤ人で、妻プリスキラとイタリアから来ていました。二人はパウロと同じ天幕作りの仕事をし、パウロは共に住んで働きました。","evidenceQuote":"he lived with them and worked, for by trade they were tent makers."},{"id":"tent-makers","kind":"fact","text":"本文では天幕作りをする職人です。具体的な材料や作業工程までは、この節だけでは分かりません。","evidenceQuote":"for by trade they were tent makers."}]}','WEB-engwebp-checked-2026-10-13','approved','1');
INSERT OR REPLACE INTO public_sources(id,book,start_chapter,start_verse,end_chapter,end_verse,kind,title,content_json,version,rights_status,active) VALUES('act-18-8','ACT','18','8','18','8','scripture','使徒 18:8（英語原文: WEB）','{"id":"act-18-8","book":"ACT","start":{"chapter":18,"verse":8},"end":{"chapter":18,"verse":8},"spoilerEnd":{"chapter":18,"verse":8},"kind":"scripture","title":"使徒 18:8（英語原文: WEB）","text":"Crispus, the ruler of the synagogue, believed in the Lord with all his house. Many of the Corinthians, when they heard, believed and were baptized.","url":"https://ebible.org/engwebp/ACT18.htm#V8","version":"WEB-engwebp-checked-2026-10-13","license":"public-domain","generationAllowed":true,"visibility":"public","reviewed":true,"claims":[{"id":"baptism-context","kind":"fact","text":"ここでは、コリントの人々が話を聞き、信じてバプテスマを受けた、という流れです。洗礼の方法や宗派ごとの理解は、この節だけから一つに決められません。","evidenceQuote":"when they heard, believed and were baptized."}]}','WEB-engwebp-checked-2026-10-13','approved','1');
INSERT OR REPLACE INTO public_sources(id,book,start_chapter,start_verse,end_chapter,end_verse,kind,title,content_json,version,rights_status,active) VALUES('act-18-12-16','ACT','18','12','18','16','scripture','使徒 18:12–16（英語原文: WEB）','{"id":"act-18-12-16","book":"ACT","start":{"chapter":18,"verse":12},"end":{"chapter":18,"verse":16},"spoilerEnd":{"chapter":18,"verse":16},"kind":"scripture","title":"使徒 18:12–16（英語原文: WEB）","text":"But when Gallio was proconsul of Achaia, the Jews with one accord rose up against Paul and brought him before the judgment seat, saying, “This man persuades men to worship God contrary to the law.” But when Paul was about to open his mouth, Gallio said to the Jews, “If indeed it were a matter of wrong or of wicked crime, you Jews, it would be reasonable that I should bear with you; but if they are questions about words and names and your own law, look to it yourselves. For I don’t want to be a judge of these matters.” So he drove them from the judgment seat.","url":"https://ebible.org/engwebp/ACT18.htm#V12","version":"WEB-engwebp-checked-2026-10-13","license":"public-domain","generationAllowed":true,"visibility":"public","reviewed":true,"claims":[{"id":"gallio-refuses","kind":"fact","text":"ガリオは、不正や犯罪なら取り上げるが、言葉や名称、ユダヤ人自身の律法に関する問題の裁判官にはなりたくない、と述べています。内心の動機までは断定できません。","evidenceQuote":"For I don’t want to be a judge of these matters."}]}','WEB-engwebp-checked-2026-10-13','approved','1');
INSERT OR REPLACE INTO public_sources(id,book,start_chapter,start_verse,end_chapter,end_verse,kind,title,content_json,version,rights_status,active) VALUES('act-18-17','ACT','18','17','18','17','scripture','使徒 18:17（英語原文: WEB）','{"id":"act-18-17","book":"ACT","start":{"chapter":18,"verse":17},"end":{"chapter":18,"verse":17},"spoilerEnd":{"chapter":18,"verse":17},"kind":"scripture","title":"使徒 18:17（英語原文: WEB）","text":"Then all the Greeks seized Sosthenes, the ruler of the synagogue, and beat him before the judgment seat. Gallio didn’t care about any of these things.","url":"https://ebible.org/engwebp/ACT18.htm#V17","version":"WEB-engwebp-checked-2026-10-13","license":"public-domain","generationAllowed":true,"visibility":"public","reviewed":true,"claims":[{"id":"sosthenes","kind":"fact","text":"ソステネは、この節で会堂の指導者として登場し、裁判の席の前で殴られた人物です。同名の別の人物との同一性は、この箇所だけでは確かめられません。","evidenceQuote":"Sosthenes, the ruler of the synagogue"}]}','WEB-engwebp-checked-2026-10-13','approved','1');
INSERT OR REPLACE INTO public_sources(id,book,start_chapter,start_verse,end_chapter,end_verse,kind,title,content_json,version,rights_status,active) VALUES('act-18-18','ACT','18','18','18','18','scripture','使徒 18:18（英語原文: WEB）','{"id":"act-18-18","book":"ACT","start":{"chapter":18,"verse":18},"end":{"chapter":18,"verse":18},"spoilerEnd":{"chapter":18,"verse":18},"kind":"scripture","title":"使徒 18:18（英語原文: WEB）","text":"Paul, having stayed after this many more days, took his leave of the brothers, and sailed from there for Syria, together with Priscilla and Aquila. He shaved his head in Cenchreae, for he had a vow.","url":"https://ebible.org/engwebp/ACT18.htm#V18","version":"WEB-engwebp-checked-2026-10-13","license":"public-domain","generationAllowed":true,"visibility":"public","reviewed":true,"claims":[{"id":"hair-vow","kind":"fact","text":"本文は、誓願があったためケンクレアで髪をそったと述べます。その誓願の具体的な内容までは、この節には書かれていません。","evidenceQuote":"He shaved his head in Cenchreae, for he had a vow."},{"id":"cenchreae-mentioned","kind":"fact","text":"この節では、ケンクレアは髪をそった場所として登場します。正確な位置や港の説明には、地理資料を別に確認する必要があります。","evidenceQuote":"He shaved his head in Cenchreae"}]}','WEB-engwebp-checked-2026-10-13','approved','1');
INSERT OR REPLACE INTO public_sources(id,book,start_chapter,start_verse,end_chapter,end_verse,kind,title,content_json,version,rights_status,active) VALUES('act-18-24-26','ACT','18','24','18','26','scripture','使徒 18:24–26（英語原文: WEB）','{"id":"act-18-24-26","book":"ACT","start":{"chapter":18,"verse":24},"end":{"chapter":18,"verse":26},"spoilerEnd":{"chapter":18,"verse":26},"kind":"scripture","title":"使徒 18:24–26（英語原文: WEB）","text":"Now a certain Jew named Apollos, an Alexandrian by race, an eloquent man, came to Ephesus. He was mighty in the Scriptures. This man had been instructed in the way of the Lord; and being fervent in spirit, he spoke and taught accurately the things concerning Jesus, although he knew only the baptism of John. He began to speak boldly in the synagogue. But when Priscilla and Aquila heard him, they took him aside, and explained to him the way of God more accurately.","url":"https://ebible.org/engwebp/ACT18.htm#V24","version":"WEB-engwebp-checked-2026-10-13","license":"public-domain","generationAllowed":true,"visibility":"public","reviewed":true,"claims":[{"id":"aquila-later","kind":"fact","text":"後の場面でプリスキラとアキラは、アポロを招き、神の道をより正確に説明しました。","evidenceQuote":"they took him aside, and explained to him the way of God more accurately."}]}','WEB-engwebp-checked-2026-10-13','approved','1');
